#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void print128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    i128 ans = n;

    while (n > 0 && n % 2 == 0) {
        n /= 2;
        ans += n;
    }

    for (int64 divisor = 3; divisor <= n / divisor; divisor += 2) {
        while (n % divisor == 0) {
            n /= divisor;
            ans += n;
        }
    }

    if (n > 1) {
        ++ans;
    }

    print128(ans);
    cout << '\n';

    return 0;
}

